import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

object GlobalInput {
    private val br = BufferedReader(InputStreamReader(System.`in`))
    private var st: StringTokenizer = StringTokenizer("")

    private fun next(): String {
        while (!st.hasMoreTokens()) {
            val line = br.readLine() ?: return ""
            st = StringTokenizer(line)
        }
        return st.nextToken()
    }

    fun getInt64(): Long = next().toLong()
    fun getInt(): Int = next().toInt()
    fun getWord(): String = next()
}

fun cube(x: Int): Long = x.toLong() * x.toLong() * x.toLong()

fun foo(n: Long): Long {
    var ans = 0L
    var k = 2
    while (true) {
        val x = n / cube(k)
        if (x == 0L) break
        ans += x
        k++
    }
    return ans
}

// najmniejszy argument, dla ktorego f(arg) zwraca prawde
// funkcja logiczna powinna byc niemalejaca
fun binSearch(f: (Long) -> Boolean, loIn: Long, upIn: Long, eps: Long): Long {
    var lo = loIn
    val up = upIn + 1
    var cnt = up - lo
    var mid: Long
    var step: Long
    while (cnt >= eps) {
        step = cnt / 2
        mid = lo + step
        if (!f(mid)) {
            lo = mid + eps
            cnt -= step + eps
        } else {
            cnt = step
        }
    }
    return lo
}

fun min(a: Int, b: Int): Int = if (a < b) a else b
fun max(a: Int, b: Int): Int = if (a < b) b else a
fun min64(a: Long, b: Long): Long = if (a < b) a else b
fun max64(a: Long, b: Long): Long = if (a < b) b else a
fun minStr(a: String, b: String): String = if (a < b) a else b
fun maxStr(a: String, b: String): String = if (a < b) b else a

fun abs(x: Int): Int = if (x < 0) -x else x
fun abs64(x: Long): Long = if (x < 0) -x else x

fun main() {
    val m = GlobalInput.getInt64()
    val mx = 4949100894494448L
    val x: (Long) -> Boolean = { n -> foo(n) >= m }

    var p = binSearch(x, 1L, mx, 1L)

    if (foo(p) != m) {
        p = -1L
    }

    println(p)
}
